from google.cloud import documentai

def validate_document_fields(extracted_data: dict, required_fields: list, confidence_threshold: float = 0.7) -> dict:
    """
    Validates required structured fields and their confidence scores.

    Args:
        extracted_data: A dictionary where keys are field names and values are
                        dictionaries containing 'value' and 'confidence'.
        required_fields: A list of field names that are required.
        confidence_threshold: The minimum confidence score required for a field to be considered valid.

    Returns:
        A dictionary with validation results, including an overall 'is_valid' status
        and detailed status for each required field.
    """
    validation_results = {
        "is_valid": True,
        "field_validations": {}
    }

    for field in required_fields:
        if field not in extracted_data:
            validation_results["is_valid"] = False
            validation_results["field_validations"][field] = {
                "present": False,
                "confidence_met": False,
                "message": f"Required field '{field}' is missing."
            }
        else:
            field_data = extracted_data[field]
            is_present = True
            confidence = field_data.get("confidence", 0.0)
            confidence_met = confidence >= confidence_threshold

            if not confidence_met:
                validation_results["is_valid"] = False
                validation_results["field_validations"][field] = {
                    "present": is_present,
                    "confidence_met": False,
                    "confidence_score": confidence,
                    "message": f"Confidence for '{field}' ({confidence:.2f}) is below threshold ({confidence_threshold:.2f})."
                }
            else:
                validation_results["field_validations"][field] = {
                    "present": is_present,
                    "confidence_met": True,
                    "confidence_score": confidence,
                    "message": f"Field '{field}' is present and confidence met."
                }
    return validation_results

from google.cloud import documentai_v1beta3 as documentai
import os

def extract_invoice_fields(file_path: str):
    """
    Extracts vendor, date, total, and line-item fields from an invoice using Google Cloud Document AI.
    """

    project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    location = "us"  # Or your preferred region, e.g., "eu"
    processor_id = "your-processor-id" # Create an invoice parser processor in Document AI

    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    # The full resource name of the processor
    # e.g.: projects/project_id/locations/location/processors/processor_id
    resource_name = f"projects/{project_id}/locations/{location}/processors/{processor_id}"

    mime_type = "application/pdf" # Assuming invoices are PDFs

    with open(file_path, "rb") as image:
        image_content = image.read()

    # Configure the process request
    request = documentai.ProcessRequest(
        name=resource_name,
        raw_document=documentai.RawDocument(content=image_content, mime_type=mime_type),
    )

    client = documentai.DocumentProcessorServiceClient()
    result = client.process_document(request=request)

    document = result.document
    extracted_data = {
        "vendor_name": None,
        "invoice_date": None,
        "total_amount": None,
        "line_items": [],
    }

    for entity in document.entities:
        if entity.type == "supplier_name":
            extracted_data["vendor_name"] = entity.mention_text
        elif entity.type == "invoice_date":
            extracted_data["invoice_date"] = entity.mention_text
        elif entity.type == "total_amount":
            extracted_data["total_amount"] = entity.mention_text
        elif entity.type == "line_item":
            item_data = {}
            for prop in entity.properties:
                if prop.type == "description":
                    item_data["description"] = prop.mention_text
                elif prop.type == "amount":
                    item_data["amount"] = prop.mention_text
                # Add other line item properties as needed
            if item_data:
                extracted_data["line_items"].append(item_data)

    return extracted_data
